INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910001, 2, -1, 0, 14, 30, 0, 1, -600, -4186, 'La terre rouge', 'Parle à Gornek, dans L''Antre.', 'Te voilà enfin. Bienvenue en Durotar, la terre que Thrall a donnée à notre peuple. Elle est rouge, elle est dure, et elle ne pardonne rien. Ici, personne ne t''offrira ta place : tu la gagneras. Gornek forme les nouveaux venus, dans L''Antre, juste à l''ouest. Va le voir et montre-lui ce que tu vaux.', 'Retourne voir Gornek.', 37711, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910001, 0, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910001, 1, 1, 'Gornek n''aime pas attendre.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910001, 1, 'Kaltunk t''envoie ? Bien. J''ai vu passer beaucoup de recrues, et peu sont restées debout. Voyons de quel bois tu es fait.');
INSERT INTO creature_queststarter (id, quest) VALUES (10176, 910001);
INSERT INTO creature_questender (id, quest) VALUES (3143, 910001);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910001, 0, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910001, 0, 0, -600, -4186);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910002, 2, -1, 0, 14, 30, 0, 1, -600, -4186, 'Les crocs de la Vallée', 'Tue 10 Sangliers tachetés dans la Vallée des épreuves.', 'Les sangliers tachetés ont pris goût à nos réserves. Ils chargent les péons et renversent les tas de bois. Ce n''est qu''un sanglier, me diras-tu. Mais un guerrier qui ne sait pas tenir face à une charge ne tiendra face à rien. Tue-en dix. Apprends comment ils frappent, et comment ils tombent.', 'Retourne voir Gornek.', 910101, 1, 3098, 10);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910002, 910001, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910002, 1, 1, 'Les sangliers rôdent encore autour du camp.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910002, 1, 'Tu as encore tes deux jambes. C''est un bon début. Prends ces bottes : la Vallée use le cuir plus vite que tu ne crois.');
INSERT INTO creature_queststarter (id, quest) VALUES (3143, 910002);
INSERT INTO creature_questender (id, quest) VALUES (3143, 910002);
