INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2) VALUES (910003, 2, -1, 0, 14, 60, 0, 1, -562, -4222, 'Des vivres pour la Vallée', 'Rapporte 6 Pommes de cactus et 6 Queues de scorpide ouvrier à Galgar.', 'La Vallée nourrit ceux qui savent chercher. Les pommes de cactus poussent au pied des grands cactus, il suffit de faire attention aux épines. Les scorpides ouvriers, eux, sont plus méchants qu''ils n''en ont l''air. Leur queue donne un bon poison pour les flèches de nos chasseurs. Rapporte-moi six pommes et six queues. Personne ne mange gratuitement ici, pas même moi.', 'Retourne voir Galgar.', 37711, 1, 11583, 6, 4862, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910003, 910001, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910003, 1, 1, 'Six pommes et six queues. Ce n''est pas si compliqué.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910003, 1, 'Voilà qui remplira les marmites et les carquois. Tu apprends vite. Prends ceci pour ta peine.');
INSERT INTO creature_queststarter (id, quest) VALUES (9796, 910003);
INSERT INTO creature_questender (id, quest) VALUES (9796, 910003);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910003, 0, 4, 1, 4, 0, 0, 1);
