INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredItemId1, RequiredItemCount1) VALUES (910004, 2, -1, 0, 14, 60, 16114, 1, -612, -4322, 'Les péons qui ne dorment plus', 'Réveille 5 Péons fainéants avec la Matraque du contremaître et rapporte la Pioche de Thazz''ril, au Convent de la Lame ardente.', 'Regarde-les ! Ils dorment au lieu de couper du bois. Mais ce n''est pas de la paresse, crois-moi. Ils me racontent tous la même chose : des lueurs vertes la nuit, à l''est, du côté des cavernes. Des petites créatures qui ricanent dans le noir. L''un d''eux s''est enfui en y laissant ma pioche. Réveille ces fainéants avec ma matraque, et va me chercher cette pioche. Mais prudence : je ne sais pas ce qui rôde là-bas.', 'Retourne voir Contremaître Thazz''ril.', 910102, 1, 10556, 5, 16332, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910004, 910001, 1);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910004, 1, 1, 'Mes péons ronflent encore, et ma pioche n''est pas revenue toute seule.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910004, 1, 'Ma pioche ! Elle sent le soufre… Alors c''est vrai, il y a quelque chose de mauvais dans ces cavernes. Il faut prévenir Zureetha. Garde ces gants, tu en auras besoin.');
INSERT INTO creature_queststarter (id, quest) VALUES (11378, 910004);
INSERT INTO creature_questender (id, quest) VALUES (11378, 910004);
