INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910005, 2, -1, 0, 14, 90, 0, 1, -629, -4228, 'Les vils quasits', 'Tue 8 Vils quasits et 6 Traqueurs gangrenés au Convent de la Lame ardente.', 'Les péons ont raison d''avoir peur. Ce que tu as vu là-bas, ce sont des démons. De petits démons, mais des démons quand même. Il n''y a qu''une façon pour qu''ils arrivent ici : quelqu''un les a appelés. Ce poison a déjà rongé notre peuple une fois, sous le joug de la Légion. Thrall ne le laissera pas revenir, et moi non plus. Va au Convent et taille-les en pièces.', 'Retourne voir Zureetha Mireloin.', 910103, 1, 3101, 8, 3102, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910005, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910005, 0, 0, 8, 0, 910002, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D05 demande D02');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910005, 0, 0, 8, 0, 910004, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D05 demande D04');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910005, 1, 1, 'Les démons grouillent encore au Convent ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910005, 1, 'Bon travail. Mais tuer les démons ne suffit pas. Celui qui les appelle est encore là-bas, j''en suis sûre. Prends cette ceinture et repose-toi un peu.');
INSERT INTO creature_queststarter (id, quest) VALUES (3145, 910005);
