INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910006, 2, -1, 0, 14, 90, 0, 1, -398, -4109, 'Sarkoth', 'Tue Sarkoth, au nord-ouest de la Vallée, et rapporte sa pince à Hana''zua.', 'Approche… Je ne peux plus marcher. Un scorpide énorme m''a attaquée, là-haut, sur la colline. Les autres l''appellent Sarkoth. Il garde ce coin depuis bien avant notre arrivée. Ce n''est pas un scorpide ouvrier : sa carapace arrête les lames mal tenues. Tue-le avant qu''il ne s''en prenne à quelqu''un d''autre. Et rapporte-moi sa pince, que je sache qu''il est mort.', 'Retourne voir Hana''zua.', 910104, 1, 4905, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910006, 910002, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910006, 1, 1, 'Sarkoth est toujours sur la colline ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910006, 1, 'Sa pince… Il ne fera plus de mal à personne. Merci. Prends ces brassards : je n''en ai plus l''usage pour l''instant.');
