INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910007, 2, -1, 0, 14, 90, 0, 1, -629, -4228, 'Le médaillon de la Lame ardente', 'Tue Yarrog Plaie-d''ombre, au fond du Convent, et rapporte le Médaillon de la Lame ardente.', 'Mes éclaireurs ont vu un orc au fond du Convent. Il porte une robe sombre et parle aux démons comme à des chiens. Il s''appelle Yarrog Plaie-d''ombre. S''il invoque des démons ici, au milieu de nos recrues, ce n''est pas un fou isolé. Il obéit à quelqu''un. Tue-le et fouille son corps. Je veux savoir pour qui il travaille.', 'Retourne voir Zureetha Mireloin.', 910105, 1, 4859, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910007, 910005, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910007, 1, 1, 'Yarrog respire encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910007, 1, 'Ce médaillon… Une lame entourée de flammes. La Lame ardente. Je croyais ce culte brisé depuis la libération des camps. Il est revenu, et il est ici, en Durotar. Prends ce plastron. Tu vas en avoir besoin.');
INSERT INTO creature_queststarter (id, quest) VALUES (3145, 910007);
INSERT INTO creature_questender (id, quest) VALUES (3145, 910007);
