INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910007, 1, 0, -629, -4228);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910008, 2, -1, 0, 14, 90, 4859, 1, 287, -4725, 'Un rapport à Orgnil', 'Apporte le Médaillon de la Lame ardente à Orgnil Marque-l''âme, à Tranchecolline.', 'Zureetha m''a montré le médaillon. Ce n''est plus une affaire pour la Vallée. Orgnil Marque-l''âme commande à Tranchecolline, au nord-est, sur la grand-route. Il traque la Lame ardente depuis des années. Porte-lui ce médaillon et raconte-lui ce que tu as vu. Tu n''es plus une recrue : tu quittes la Vallée. Sois digne de la Horde.', 'Retourne voir Orgnil Marque-l''âme.', 37711, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910008, 0, 1);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910008, 0, 0, 8, 0, 910006, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D08 demande D06');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910008, 0, 0, 8, 0, 910007, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D08 demande D07');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910008, 1, 1, 'Tu as quelque chose pour moi ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910008, 1, 'La Lame ardente… Je reconnais ce travail. Ces chiens ont vendu notre peuple aux démons une fois. Ils ne recommenceront pas sous les yeux de Thrall. Assieds-toi. Nous avons à parler.');
INSERT INTO creature_queststarter (id, quest) VALUES (3143, 910008);
INSERT INTO creature_questender (id, quest) VALUES (3142, 910008);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910008, 0, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910008, 0, 0, 287, -4725);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910009, 2, -1, 0, 14, 150, 0, 1, 275, -4709, 'Les traîtres de Tiragarde', 'Tue 10 Marins et 8 Soldats de marine de Kul Tiras au Donjon de Tiragarde.', 'Orgnil chasse les sorciers. Moi, je garde la route. Au sud-est, sur la côte, les humains de Kul Tiras se sont retranchés dans le Donjon de Tiragarde. Leur amiral est mort à Theramore, mais ses hommes servent encore sa mémoire. Ils attaquent nos patrouilles et espionnent nos chemins. Tant qu''ils tiennent ce donjon, aucune caravane n''est en sécurité. Va leur montrer ce qu''il en coûte de rester sur nos terres.', 'Retourne voir Gar''Thok.', 910106, 1, 3128, 10, 3129, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910009, 910008, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910009, 1, 1, 'Les Kul Tirassiens tiennent toujours leurs murs ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910009, 1, 'Ils comprendront peut-être, cette fois. Mais il en reste, et leur officier n''est pas tombé. Prends ces jambières : elles viennent de nos forges.');
INSERT INTO creature_queststarter (id, quest) VALUES (3139, 910009);
INSERT INTO creature_questender (id, quest) VALUES (3139, 910009);
