INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910010, 2, -1, 0, 14, 150, 0, 1, 385, -4600, 'L''épave des gnomes', 'Rapporte 3 Outils gnomes, sur la Côte des naufrages, à Furl Morguefront.', 'Du haut de ma tour, on voit jusqu''à la mer. Depuis des jours, des marins de Kul Tiras fouillent l''épave d''un navire gnome échoué au sud-est. Ils emportent des caisses vers le donjon. Je n''aime pas ça. Des outils gnomes, entre des mains humaines, ça peut devenir des machines de siège. Va voir ce qu''ils cherchent et rapporte-moi trois de ces outils. Les clampants et les makruras ne te laisseront pas faire tranquillement.', 'Retourne voir Furl Morguefront.', 37711, 2, 4863, 3);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910010, 910008, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910010, 1, 1, 'Alors, ces outils ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910010, 1, 'Des pièces de canon et des engrenages… Ils veulent fortifier leurs murs, ou pire. Gar''Thok doit le savoir. Merci, et prends ceci.');
INSERT INTO creature_queststarter (id, quest) VALUES (3147, 910010);
INSERT INTO creature_questender (id, quest) VALUES (3147, 910010);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910010, 0, 4, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910010, 0, 0, 10, -5284), (910010, 0, 1, -3, -5252), (910010, 0, 2, -35, -5239), (910010, 0, 3, -67, -5252), (910010, 0, 4, -80, -5284), (910010, 0, 5, -67, -5316), (910010, 0, 6, -35, -5329), (910010, 0, 7, -3, -5316);
