INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910010, 1, 0, 385, -4600);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910011, 2, -1, 0, 14, 180, 0, 1, 1000, -4414, 'Des vents dans le désert', 'Rapporte 5 Sacs de ravitaillement du Canyon de Tranchevent à Rezlak.', 'Ah, enfin des bras solides ! Écoute, j''ai un problème. Ma caravane montait vers Orgrimmar avec des vivres pour les grunts. Les harpies Terrevent nous sont tombées dessus dans le canyon. Elles ont tout pris, tout éparpillé ! Ces sacs valent une fortune, et la garnison en a besoin. Rapporte-m''en cinq. Je saurai me montrer généreux, foi de gobelin.', 'Retourne voir Rezlak.', 910107, 1, 4918, 5);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910011, 910008, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910011, 1, 1, 'Mes sacs, mes beaux sacs…');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910011, 1, 'Cinq sacs ! Pas trop abîmés, en plus. Tiens, une cape. Elle était dans le lot, mais je dirai que les harpies l''ont mangée.');
INSERT INTO creature_queststarter (id, quest) VALUES (3293, 910011);
INSERT INTO creature_questender (id, quest) VALUES (3293, 910011);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910011, 0, 4, 1, 4, 0, 0, 1);
