INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910011, 1, 0, 1000, -4414);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910012, 2, -1, 0, 14, 180, 0, 1, 275, -4709, 'Les ordres de l''amiral', 'Tue le Lieutenant Benedict, au Donjon de Tiragarde, et rapporte les Ordres de l''amiral Portvaillant.', 'Le Lieutenant Benedict commande Tiragarde. Il garde sur lui les derniers ordres de l''amiral Portvaillant, et des messages lui arrivent encore par la mer. Je veux ces papiers. Je veux savoir ce que ces humains préparent, et pour qui. Benedict se cache au sommet du donjon, entouré de ses meilleurs soldats. Ce sera plus dur que tout ce que tu as fait jusqu''ici. Prépare-toi bien avant d''y monter.', 'Retourne voir Gar''Thok.', 910108, 1, 4883, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910012, 910009, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910012, 1, 1, 'Benedict tient toujours son donjon ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910012, 1, 'Montre-moi ça… Ils parlent d''un accord avec des « sorciers à la lame enflammée ». Des cartes des souterrains d''Orgrimmar contre de l''or et des armes. La Lame ardente se sert même des humains contre nous. Prends cette épée : elle vient d''un officier de Kul Tiras. Orgnil doit lire ceci.');
INSERT INTO creature_queststarter (id, quest) VALUES (3139, 910012);
INSERT INTO creature_questender (id, quest) VALUES (3139, 910012);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910012, 0, 4, 1, 4, 0, 0, 1);
