INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910012, 1, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910012, 1, 0, 275, -4709);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2) VALUES (910013, 2, -1, 0, 14, 180, 0, 1, 272, -4651, 'Le cercle qui se resserre', 'Tue 8 Hurans et 8 Éclaireurs Tranchecrins dans les Terres des Tranchecrins.', 'Je parcours les pistes du nord chaque jour. Chaque jour, les huréceros Tranchecrins s''approchent un peu plus de nos murs. Ils viennent des Tarides et se croient chez eux. Leurs éclaireurs comptent nos grunts, leurs hurans pillent nos pièges. Repousse-les vers l''ouest. Un conseil : leur kraal, plus au nord, est bien mieux gardé. Ne t''y risque pas avant d''être prêt.', 'Retourne voir Takrin Cherchevoie.', 910109, 1, 3111, 8, 3112, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910013, 910008, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910013, 1, 1, 'Les huréceros sont toujours à nos portes ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910013, 1, 'Ils réfléchiront avant de revenir. Tu as l''œil d''un éclaireur et la main d''un guerrier. Ce plastron est à toi. Mais souviens-toi : le kraal du nord, la géomaîtresse Mouchette et ses gardes de guerre. Un jour, il faudra s''en occuper aussi.');
INSERT INTO creature_queststarter (id, quest) VALUES (3336, 910013);
INSERT INTO creature_questender (id, quest) VALUES (3336, 910013);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910013, 0, 0, 1, 4, 0, 0, 1);
