INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910013, 1, 1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910013, 1, 0, 120, -4480), (910013, 1, 1, 107, -4448), (910013, 1, 2, 75, -4435), (910013, 1, 3, 43, -4448), (910013, 1, 4, 30, -4480), (910013, 1, 5, 43, -4512), (910013, 1, 6, 75, -4525), (910013, 1, 7, 107, -4512);
