INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910013, 2, 0, 272, -4651);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910014, 2, -1, 0, 14, 180, 0, 1, -826, -4921, 'Vers Sen''jin', 'Va voir Maître Gadrin, au Village de Sen''jin.', 'Ces ordres confirment ce que je craignais. La Lame ardente ne combat pas seule. Elle souffle sur chaque braise : les humains, les huréceros, et qui sait encore. Si elle veut affaiblir Orgrimmar, elle cherchera aussi nos alliés trolls. Les Sombrelances de Vol''jin vivent au sud, à Sen''jin. Ils ont leurs propres malheurs avec Zalazane. Va voir Maître Gadrin. Aide-le, et ouvre l''œil.', 'Retourne voir Maître Gadrin.', 37711, 2);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910014, 910012, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910014, 1, 1, 'Gadrin t''attend au sud.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910014, 1, 'Un envoyé d''Orgnil ? Bienvenue à Sen''jin, l''ami. Nous avons besoin de bras, et le tien me paraît solide. Viens, je vais t''expliquer.');
INSERT INTO creature_queststarter (id, quest) VALUES (3142, 910014);
INSERT INTO creature_questender (id, quest) VALUES (3188, 910014);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910014, 0, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910014, 0, 0, -826, -4921);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2) VALUES (910015, 2, -1, 0, 14, 240, 0, 1, -814, -4921, 'L''esprit clair', 'Rapporte 4 Yeux de makrura intacts et 8 Mucus de clampant de la Grève des Sombrelances.', 'Zalazane était l''un des nôtres. Un grand guide spirituel. Puis la folie l''a pris, et il a ensorcelé nos frères sur les îles de l''Écho. Ses maléfices brouillent l''esprit de ceux qui l''approchent. Je peux préparer une potion pour garder l''esprit clair. Il me faut des yeux de makrura, intacts, et du mucus de clampant. Tu trouveras tout ça sur la grève, juste au sud.', 'Retourne voir Maître Vornal.', 37711, 3, 4887, 4, 4888, 8);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910015, 910014, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910015, 1, 1, 'Les makruras ne vont pas te donner leurs yeux gentiment, hein ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910015, 1, 'Parfait. Avec ça, nos guerriers pourront poser le pied sur les îles sans perdre la tête. Prends ces Marques : tu les as bien gagnées.');
INSERT INTO creature_queststarter (id, quest) VALUES (3304, 910015);
INSERT INTO creature_questender (id, quest) VALUES (3304, 910015);
