INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3, ObjectiveText1, ObjectiveText2, ObjectiveText3) VALUES (910016, 2, -1, 0, 14, 240, 0, 1, -775, -4830, 'Les plans des Kolkar', 'Lis les trois Plans d''attaque des Kolkar, à la Combe des Kolkar.', 'Les centaures Kolkar sont arrivés des Tarides il y a peu. Ils ont installé un camp dans la combe, à l''ouest. Mes guetteurs les ont vus dessiner sur des peaux, autour d''un feu. Des plans d''attaque, j''en suis sûr. Les centaures sont des pillards, pas des stratèges. Quelqu''un les aide à réfléchir. Va lire ces plans, et détruis-les.', 'Retourne voir Lar Fouinebroche.', 910110, 1, -3189, 1, -3190, 1, -3192, 1, 'Plan d''attaque : Vallée des épreuves lu', 'Plan d''attaque : Village de Sen''jin lu', 'Plan d''attaque : Orgrimmar lu');
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910016, 910014, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910016, 1, 1, 'Tu as vu leurs plans ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910016, 1, 'La Vallée, Sen''jin… et Orgrimmar, par les souterrains. Les centaures ne connaissent pas les souterrains d''Orgrimmar. Quelqu''un les leur a montrés. Prends ces gants, et va voir leur chef.');
INSERT INTO creature_queststarter (id, quest) VALUES (3140, 910016);
INSERT INTO creature_questender (id, quest) VALUES (3140, 910016);
