INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910017, 2, -1, 0, 14, 270, 0, 1, -775, -4830, 'Le seigneur de guerre', 'Tue le Seigneur de guerre Kolkanis, à la Combe des Kolkar.', 'Kolkanis mène les Kolkar de la combe. Sans lui, ses guerriers repartiront vers les Tarides. Il ne quitte jamais sa tente, au fond du camp, et ses estafettes le gardent bien. Il est plus fort que tout ce que tu as affronté sur cette côte. Ne te jette pas sur lui à l''aveugle. Nettoie le camp s''il le faut, puis frappe à la tête.', 'Retourne voir Lar Fouinebroche.', 37711, 3, 5808, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910017, 910016, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910017, 1, 1, 'Kolkanis vit encore ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910017, 1, 'Kolkanis est mort ! Les centaures vont se disperser. Sen''jin te doit une fière chandelle, l''ami.');
INSERT INTO creature_queststarter (id, quest) VALUES (3140, 910017);
INSERT INTO creature_questender (id, quest) VALUES (3140, 910017);
