INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910018, 2, -1, 0, 14, 240, 0, 1, -798, -4921, 'Proie nécessaire', 'Rapporte 4 Fourrures de tigre de Durotar, prises sur les îles de l''Écho, à Vel''rin Croc.', 'Nos éclaireurs doivent débarquer sur les îles sans se faire voir. Les gens de Zalazane surveillent les plages. Avec des capes en fourrure de tigre, nos chasseurs se fondent dans les fourrés. Les tigres de Durotar rôdent sur les îles mêmes. Ils sont rapides et vicieux. Rapporte-moi quatre belles fourrures.', 'Retourne voir Vel''rin Croc.', 910111, 1, 4892, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910018, 910014, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910018, 1, 1, 'Les tigres t''ont donné du fil à retordre ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910018, 1, 'Belles fourrures. Mes éclaireurs passeront inaperçus. Prends ces bottes : elles sont faites pour la plage.');
INSERT INTO creature_queststarter (id, quest) VALUES (3194, 910018);
INSERT INTO creature_questender (id, quest) VALUES (3194, 910018);
