INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910019, 2, -1, 0, 14, 270, 0, 1, -826, -4921, 'Le crâne de Minshina', 'Reprends le Crâne de Minshina, auprès des Sombrelances emprisonnés de l''île de l''Écho.', 'Minshina était une grande prêtresse de notre peuple. Zalazane a volé son crâne et s''en sert pour nourrir ses maléfices. Il le garde au milieu de ses prisonniers, sur la grande île. La potion de Vornal protège nos guerriers ; toi, tu passeras devant. Traverse à gué et reprends-le. Sans ce crâne, Zalazane perdra une partie de son pouvoir. Ses trolls ensorcelés te barreront la route, mais ce ne sont que des marionnettes.', 'Retourne voir Maître Gadrin.', 910112, 1, 4864, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910019, 910015, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910019, 1, 1, 'Le crâne de Minshina est toujours entre ses mains ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910019, 1, 'Minshina… Elle reposera enfin auprès des siens. Tu as rendu un grand service aux Sombrelances. Cette ceinture était à mon père. Porte-la.');
INSERT INTO creature_queststarter (id, quest) VALUES (3188, 910019);
INSERT INTO creature_questender (id, quest) VALUES (3188, 910019);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910019, 0, 4, 1, 4, 0, 0, 1);
