INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910019, 1, 0, -826, -4921);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredItemId1, RequiredItemCount1) VALUES (910020, 2, -1, 0, 14, 300, 0, 1, -826, -4921, 'Zalazane', 'Tue 8 Trolls vaudou et 8 Trolls maléficiés, puis abats Zalazane et rapporte sa tête.', 'Le moment est venu. Zalazane a perdu le crâne, ses gardes ne voient plus nos éclaireurs, et nos guerriers ont l''esprit clair. Vol''jin m''a fait porter sa réponse depuis Orgrimmar : il faut en finir. Zalazane était son ami, et c''est à notre peuple de laver cette honte. Mais il te demande de frapper le premier coup. Tue ses fidèles, puis abats Zalazane. Rapporte-moi sa tête : je l''enverrai à Vol''jin.', 'Retourne voir Maître Gadrin.', 910113, 1, 3206, 8, 3207, 8, 4866, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910020, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910020, 0, 0, 8, 0, 910018, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D20 demande D18');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910020, 0, 0, 8, 0, 910019, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D20 demande D19');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910020, 1, 1, 'Zalazane danse encore sur nos îles ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910020, 1, 'C''est fini, alors. Vol''jin pleurera son vieil ami, mais il dormira mieux. Mes guerriers ont fouillé sa hutte. Zalazane recevait des visiteurs : des orcs en robe sombre, venus du nord. Ils lui promettaient des forces qu''il ne comprenait pas. Tu sais qui ils sont. Prends cette arme, et retourne voir Orgnil. Les Sombrelances se souviendront de toi.');
INSERT INTO creature_queststarter (id, quest) VALUES (3188, 910020);
INSERT INTO creature_questender (id, quest) VALUES (3188, 910020);
