INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910021, 2, -1, 0, 14, 300, 0, 1, 742, -4242, 'L''égaré', 'Retrouve l''Amulette de Kron sur les Crocilisques Gueule-d''effroi de La Furie-du-Sud.', 'Mon fils Kron est parti chasser vers la rivière, il y a trois jours. Il n''est pas revenu. Les bêtes du coin ne sont plus les mêmes. Les sangliers ont les yeux verts, les raptors bavent une écume noire. Quelque chose les rend fous. Kron portait une amulette, un cadeau de son père. Je t''en supplie, trouve-le, ou trouve au moins ce qui reste de lui. Les crocilisques de la Furie-du-Sud sont les pires de tous.', 'Retourne voir Misha Tor''kren.', 37711, 4, 4891, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910021, 910020, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910021, 1, 1, 'Tu as des nouvelles de Kron ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910021, 1, 'Son amulette… Alors il est mort. Merci de me l''avoir rapportée. Je la garderai près du feu. Prends ces Marques. Kron aurait voulu que sa mort serve à quelqu''un.');
INSERT INTO creature_queststarter (id, quest) VALUES (3193, 910021);
INSERT INTO creature_questender (id, quest) VALUES (3193, 910021);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910021, 0, 4, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910021, 0, 0, 326, -3848), (910021, 0, 1, 313, -3816), (910021, 0, 2, 281, -3803), (910021, 0, 3, 249, -3816), (910021, 0, 4, 236, -3848), (910021, 0, 5, 249, -3880), (910021, 0, 6, 281, -3893), (910021, 0, 7, 313, -3880);
