INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910021, 1, 0, 742, -4242);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910022, 2, -1, 0, 14, 270, 0, 1, 1279, -4189, 'Le venin des queues-venin', 'Rapporte 5 Glandes à venin de queue-venin à Rhinag.', 'Trois de mes ouvriers ont été piqués cette semaine. Trois ! Avant, les queues-venin fuyaient la ferme. Maintenant, ils viennent jusqu''aux enclos. Certains ont la carapace qui luit, verte comme un feu de démon. Leur venin est plus fort qu''avant, et nos remèdes ne marchent plus. Avec leurs glandes, je peux préparer un antidote. Il m''en faut cinq.', 'Retourne voir Rhinag.', 37711, 4, 4886, 5);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910022, 910020, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910022, 1, 1, 'Mes ouvriers ne tiendront pas longtemps.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910022, 1, 'Cinq glandes. Je me mets au travail tout de suite. Ces scorpides corrompus… Orgnil doit entendre parler de ça. Voilà pour toi.');
INSERT INTO creature_queststarter (id, quest) VALUES (3190, 910022);
INSERT INTO creature_questender (id, quest) VALUES (3190, 910022);
