INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910023, 2, -1, 0, 14, 300, 0, 1, 1102, -4945, 'Les colliers brûlants', 'Prends 6 Colliers brûlants aux fidèles de la Lame ardente, dans la Caverne des Terrevent, et porte-les à Margoz.', 'Gadrin m''a fait prévenir. Des orcs en robe sombre chez Zalazane, des cartes chez les humains, des plans chez les centaures. Et maintenant des bêtes corrompues dans nos fermes. Tout mène au même endroit. La Lame ardente a un repaire dans la Caverne des Terrevent, au nord, près du Ravin asséché. Ses sectateurs portent des colliers qui brûlent au toucher. Rapporte-m''en six, et porte-les à Margoz. Ce vieux chaman surveille le culte depuis des années, il saura les lire. Ne prends pas ces fanatiques à la légère : ce ne sont plus des quasits.', 'Retourne voir Margoz.', 910114, 1, 4871, 6);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910023, 910020, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910023, 1, 1, 'Tu as les colliers ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910023, 1, 'Orgnil t''envoie, hein ? Fais voir. Ces colliers sont liés par une magie de feu gangrené. Celui qui les forge vit sur les Falaises du Tonnerre, à l''ouest. Et ceux qui les portent se rassemblent au Rocher du crâne, juste au nord de mon camp. Garde ces brassards, ils te protégeront un peu de leurs flammes.');
INSERT INTO creature_queststarter (id, quest) VALUES (3142, 910023);
INSERT INTO creature_questender (id, quest) VALUES (3208, 910023);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910023, 0, 4, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910023, 0, 0, 915, -4745), (910023, 0, 1, 902, -4713), (910023, 0, 2, 870, -4700), (910023, 0, 3, 838, -4713), (910023, 0, 4, 825, -4745), (910023, 0, 5, 838, -4777), (910023, 0, 6, 870, -4790), (910023, 0, 7, 902, -4777);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910023, 1, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910023, 1, 0, 1102, -4945);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910024, 2, -1, 0, 14, 300, 0, 1, 1102, -4945, 'De sombres orages', 'Tue Féplouf Sombrorage, sur les Falaises du Tonnerre, et rapporte sa griffe.', 'Sur les Falaises du Tonnerre, à l''ouest de la grand-route, un sorcier de la Lame appelle des orages qui ne sont pas naturels. Il s''appelle Féplouf Sombrorage. Ses éclairs nourrissent les lézards-tonnerre et rendent fous les foudroyants. Il fabrique ces colliers et les distribue aux recrues du culte. C''est l''un de leurs maîtres. Tue-le et rapporte-moi sa griffe. Il est dangereux. Si tu n''es pas prêt, attends de l''être.', 'Retourne voir Margoz.', 910115, 1, 4869, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910024, 910023, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910024, 1, 1, 'L''orage gronde encore là-haut.');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910024, 1, 'La griffe de Féplouf. L''orage va se calmer. Mais avant de mourir, il a dû prévenir ses frères. Prends ces jambières.');
INSERT INTO creature_queststarter (id, quest) VALUES (3208, 910024);
INSERT INTO creature_questender (id, quest) VALUES (3208, 910024);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910024, 0, 4, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910024, 0, 0, 914, -4190), (910024, 0, 1, 901, -4158), (910024, 0, 2, 869, -4145), (910024, 0, 3, 837, -4158), (910024, 0, 4, 824, -4190), (910024, 0, 5, 837, -4222), (910024, 0, 6, 869, -4235), (910024, 0, 7, 901, -4222);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910024, 1, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910024, 1, 0, 1102, -4945);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910025, 2, -1, 0, 14, 300, 0, 1, 1102, -4945, 'Ombres ardentes', 'Tue Gazz''uz, au Rocher du crâne, et rapporte l''Œil de l''ombre ardente.', 'Le Rocher du crâne est le cœur du culte en surface. Juste sous les murs d''Orgrimmar, tu te rends compte ? Leur chef là-bas s''appelle Gazz''uz. Il porte un œil de pierre qui voit dans les ombres et lui parle. Je veux cet œil. Il nous dira où mène la Lame. Gazz''uz est entouré de fanatiques et d''apprentis. Fais le ménage autour de lui, ou il te submergera.', 'Retourne voir Margoz.', 910116, 1, 4903, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910025, 910023, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910025, 1, 1, 'Gazz''uz est toujours vivant ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910025, 1, 'L''Œil de l''ombre ardente… Je vois à travers. Des tunnels. Une caverne de feu, sous la ville. Des orcs en robe, et quelque chose de bien plus grand qui a faim. Prends ce bouclier. Il te le faudra là où tu vas aller.');
INSERT INTO creature_queststarter (id, quest) VALUES (3208, 910025);
INSERT INTO creature_questender (id, quest) VALUES (3208, 910025);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910025, 0, 4, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910025, 0, 0, 1514, -4705), (910025, 0, 1, 1501, -4673), (910025, 0, 2, 1469, -4660), (910025, 0, 3, 1437, -4673), (910025, 0, 4, 1424, -4705), (910025, 0, 5, 1437, -4737), (910025, 0, 6, 1469, -4750), (910025, 0, 7, 1501, -4737);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910025, 1, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910025, 1, 0, 1102, -4945);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1) VALUES (910026, 2, -1, 0, 14, 300, 0, 1, 1460, -4700, 'Le seuil du Gouffre', 'Parle à Ruga Brise-cendre, devant la faille du Rocher du crâne.', 'L''œil me l''a montré : la Lame ardente a percé le roc. Une faille, au fond du Rocher du crâne, descend jusqu''au Gouffre de Ragefeu, sous Orgrimmar. Ceux qui s''y cachent se nomment la Lame brûlante. Ils servent un démon, Taragaman l''Affameur. Orgnil a fait garder la faille par Ruga Brise-cendre. Va la voir. Mais écoute-moi bien : on ne descend pas dans ce gouffre comme un touriste. Les troggs, les démonistes, le feu de la terre… Si les huréceros, les harpies ou les camps du culte te font encore peur, tu n''as rien à faire en bas. Nettoie la région d''abord.', 'Retourne voir Ruga Brise-cendre.', 37711, 4);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910026, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910026, 0, 0, 8, 0, 910024, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D26 demande D24');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910026, 0, 0, 8, 0, 910025, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D26 demande D25');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910026, 1, 1, 'La faille t''attend. Toi, es-tu prêt ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910026, 1, 'Margoz t''envoie ? Alors tu sais ce qui t''attend. Personne ne passe cette faille sans avoir prouvé qu''il connaît sa terre. Quand Durotar parlera de toi, quand ses camps seront tombés, je te laisserai descendre. Pas avant.');
INSERT INTO creature_queststarter (id, quest) VALUES (3208, 910026);
INSERT INTO creature_questender (id, quest) VALUES (910001, 910026);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910026, 0, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910026, 0, 0, 1460, -4700);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredNpcOrGo3, RequiredNpcOrGoCount3) VALUES (910027, 2, -1, 0, 2437, 360, 0, 1, 1460, -4700, 'Les troggs des profondeurs', 'Dans le Gouffre de Ragefeu, tue 8 Troggs et 6 Chamans Ragefeu, puis leur chef, Lorgnesilex.', 'Avant la Lame, le Gouffre appartenait aux troggs. Des brutes des profondeurs, que le culte laisse vivre pour garder l''entrée. Leur chef s''appelle Lorgnesilex. Il croit être le maître des lieux. Montre-lui le contraire. Tant que les troggs tiennent la première caverne, tu ne pourras pas avancer. Ouvre-nous le chemin.', 'Retourne voir Ruga Brise-cendre.', 910117, 1, 11318, 8, 11319, 6, 11517, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910027, 910026, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910027, 1, 1, 'Les troggs bloquent toujours le passage ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910027, 1, 'Lorgnesilex est mort ? Bien. Le chemin est ouvert. Prends cette ceinture, faite de cuir de trogg. Ce n''est que le début.');
INSERT INTO creature_queststarter (id, quest) VALUES (910001, 910027);
INSERT INTO creature_questender (id, quest) VALUES (910001, 910027);
