INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredItemId1, RequiredItemCount1) VALUES (910028, 2, -1, 0, 2437, 360, 0, 1, 1460, -4700, 'La sacoche du Totem-sinistre', 'Retrouve Maur Totem-sinistre dans le Gouffre de Ragefeu et rapporte sa sacoche.', 'Un tauren est descendu dans le Gouffre il y a quelques jours. Maur, du clan Totem-sinistre. Ce clan ne nous aime pas, et il n''aime pas Cairne non plus. Que faisait-il chez la Lame brûlante ? Mes guetteurs l''ont vu entrer, pas sortir. Retrouve-le, mort ou vif. Et rapporte-moi sa sacoche.', 'Retourne voir Ruga Brise-cendre.', 37711, 5, 14381, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910028, 910026, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910028, 1, 1, 'Maur ? Sa sacoche ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910028, 1, 'Des lettres… Les Totem-sinistre voulaient s''allier à la Lame brûlante contre Thrall et Cairne. Le culte cherche des alliés partout. Cairne devra l''apprendre, mais ça ne nous regarde pas ici. Prends ces Marques.');
INSERT INTO creature_queststarter (id, quest) VALUES (910001, 910028);
INSERT INTO creature_questender (id, quest) VALUES (910001, 910028);
INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910028, 0, 4, 1, 4, 0, 0, 1);
