INSERT INTO quest_poi (QuestID, id, ObjectiveIndex, MapID, WorldMapAreaId, Floor, Priority, Flags) VALUES (910028, 1, -1, 1, 4, 0, 0, 1);
INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910028, 1, 0, 1460, -4700);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1, RequiredNpcOrGo2, RequiredNpcOrGoCount2, RequiredItemId1, RequiredItemCount1, RequiredItemId2, RequiredItemCount2) VALUES (910029, 2, -1, 0, 2437, 360, 0, 1, 1460, -4700, 'Le pouvoir de détruire', 'Prends Les Sorts de l''Ombre et Les Incantations du Néant aux démonistes du Gouffre, et tue Jergosh l''Invocateur et Bazzalan.', 'La Lame brûlante a deux chefs. Jergosh l''Invocateur ouvre les portes aux démons. Bazzalan, le satyre, lui murmure ses ordres. Leurs démonistes gardent deux grimoires : les Sorts de l''Ombre et les Incantations du Néant. Avec ces livres, ils peuvent appeler pire que des quasits. Arrache-leur ces livres, et abats leurs chefs. Sans eux, la Lame n''est qu''une bande de fanatiques.', 'Retourne voir Ruga Brise-cendre.', 910118, 1, 11518, 1, 11519, 1, 14395, 1, 14396, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910029, 910026, 0);
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910029, 1, 1, 'Jergosh et Bazzalan tiennent encore le fond du Gouffre ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910029, 1, 'Les deux grimoires… Je les remettrai à Orgnil, il saura les détruire. Jergosh et Bazzalan sont tombés. Prends ces jambières, et garde des forces pour la suite. Il reste l''Affameur.');
INSERT INTO creature_queststarter (id, quest) VALUES (910001, 910029);
INSERT INTO creature_questender (id, quest) VALUES (910001, 910029);
