INSERT INTO quest_poi_points (QuestID, Idx1, Idx2, X, Y) VALUES (910029, 4, 0, 1460, -4700);
INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, StartItem, POIContinent, POIx, POIy, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RewardItem2, RewardAmount2, RequiredItemId1, RequiredItemCount1) VALUES (910030, 2, -1, 0, 2437, 360, 0, 1, 287, -4725, 'Le cœur de l''Affameur', 'Tue Taragaman l''Affameur, au fond du Gouffre, et porte son cœur à Orgnil Marque-l''âme.', 'C''est lui que l''œil de Gazz''uz a vu. Taragaman l''Affameur. Un démon de la Légion, nourri de feu et de chair. Toute la Lame brûlante le sert. Tant qu''il vit, le culte renaîtra, encore et encore. Descends au fond du Gouffre et arrache-lui le cœur. Puis porte-le à Orgnil. C''est à lui de dire à Thrall que Durotar est purgée.', 'Retourne voir Orgnil Marque-l''âme.', 910119, 1, 37711, 5, 14540, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, ProvidedItemCount) VALUES (910030, 0, 0);
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910030, 0, 0, 8, 0, 910027, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D30 demande D27');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910030, 0, 0, 8, 0, 910028, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D30 demande D28');
INSERT INTO conditions (SourceTypeOrReferenceId, SourceGroup, SourceEntry, SourceId, ElseGroup, ConditionTypeOrReference, ConditionTarget, ConditionValue1, ConditionValue2, ConditionValue3, NegativeCondition, ErrorType, ErrorTextId, ScriptName, Comment) VALUES (19, 0, 910030, 0, 0, 8, 0, 910029, 0, 0, 0, 0, 0, '', 'Sol''Azeroth v3 : D30 demande D29');
INSERT INTO quest_request_items (ID, EmoteOnComplete, EmoteOnIncomplete, CompletionText) VALUES (910030, 1, 1, 'Alors, le Gouffre ?');
INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910030, 1, 'Le cœur de l''Affameur… Il bat encore un peu. Je vais le brûler moi-même. Grâce à toi, la Lame ardente a perdu ses chefs, son démon et son repaire. Thrall saura ton nom. Durotar est à toi, autant qu''à nous.');
INSERT INTO creature_queststarter (id, quest) VALUES (910001, 910030);
